1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioOutput {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	const CURSE_SURCHARGE_RATE = 0.5;
58	const HIGH_ENCHANTMENT_THRESHOLD = 5;
59	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
60	const LOYALTY_THRESHOLD_YEARS = 2;
61	const LOYALTY_DISCOUNT_RATE = 0.2;
62	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
63	const DEDUCTIBLE_PER_DAMAGE = 100;
64	const CAP_MULTIPLIER = 2;
65	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
66	const HALF_REIMBURSEMENT_RATE = 0.5;
67	
68	const INSURANCE_VALUES: Record<string, number> = {
69	  sword: 1000,
70	  amulet: 600,
71	  staff: 800,
72	  potion: 400,
73	  rune: 250,
74	  moonstone: 250,
75	};
76	
77	const BASE_PREMIUMS: Record<string, number> = {
78	  sword: 100,
79	  amulet: 60,
80	  staff: 80,
81	  potion: 40,
82	  rune: 25,
83	  moonstone: 25,
84	};
85	
86	const BLOCK_SIZE = 3;
87	const BLOCK_BASE_PREMIUM = 60;
88	
89	const countByType = (items: Item[]): Map<string, number> => {
90	  const counts = new Map<string, number>();
91	  for (const item of items) {
92	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
93	  }
94	  return counts;
95	};
96	
97	const basePremiumOfType = (type: string): number => {
98	  const premium = BASE_PREMIUMS[type];
99	  if (premium === undefined) {
100	    throw new Error(`unknown item type: ${type}`);
101	  }
102	  return premium;
103	};
104	
105	const basePremiumOfAlikeItems = (type: string, count: number): number =>
106	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumOfType(type);
107	
108	const policyBasePremium = (items: Item[]): number =>
109	  [...countByType(items)].reduce(
110	    (total, [type, count]) => total + basePremiumOfAlikeItems(type, count),
111	    0,
112	  );
113	
114	const firstInsuranceSurcharge = (policyBase: number): number =>
115	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
116	
117	const itemBasePremium = (item: Item): number => basePremiumOfType(item.type);
118	
119	const isCursed = (item: Item): boolean => item.cursed === true;
120	
121	const isHighlyEnchanted = (item: Item): boolean =>
122	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
123	
124	const curseSurcharge = (item: Item): number =>
125	  isCursed(item) ? itemBasePremium(item) * CURSE_SURCHARGE_RATE : 0;
126	
127	const highEnchantmentSurcharge = (item: Item): number =>
128	  isHighlyEnchanted(item)
129	    ? itemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
130	    : 0;
131	
132	const itemSurchargeTotal = (items: Item[]): number =>
133	  items.reduce(
134	    (total, item) => total + curseSurcharge(item) + highEnchantmentSurcharge(item),
135	    0,
136	  );
137	
138	const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
139	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
140	    ? policyBase * LOYALTY_DISCOUNT_RATE
141	    : 0;
142	
143	const followUpContractDiscount = (policyBase: number, previousQuotes: number): number =>
144	  previousQuotes > 0 ? policyBase * FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0;
145	
146	const policyWideAdjustments = (
147	  policyBase: number,
148	  customer: Customer,
149	  previousQuotes: number,
150	): number =>
151	  firstInsuranceSurcharge(policyBase) -
152	  loyaltyDiscount(policyBase, customer) -
153	  followUpContractDiscount(policyBase, previousQuotes);
154	
155	const quote = (
156	  step: QuoteStep,
157	  customer: Customer,
158	  previousQuotes: number,
159	): QuoteResult => {
160	  const policyBase = policyBasePremium(step.items);
161	  const premiumBeforeRounding =
162	    policyBase +
163	    itemSurchargeTotal(step.items) +
164	    policyWideAdjustments(policyBase, customer, previousQuotes) +
165	    PROCESSING_FEE;
166	  return { premium: Math.ceil(premiumBeforeRounding) };
167	};
168	
169	interface Policy {
170	  items: Item[];
171	  remainingCap: number;
172	}
173	
174	const insuranceSum = (items: Item[]): number =>
175	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
176	
177	const isHalfCovered = (item: Item): boolean =>
178	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
179	
180	// How much of the damage the policy covers, before the deductible is taken off.
181	const coveredAmount = (damage: Damage, item: Item): number =>
182	  isHalfCovered(item) ? damage.amount * HALF_REIMBURSEMENT_RATE : damage.amount;
183	
184	const payoutForDamage = (damage: Damage, item: Item): number =>
185	  Math.max(0, coveredAmount(damage, item) - DEDUCTIBLE_PER_DAMAGE);
186	
187	const damagedItem = (policy: Policy, damage: Damage): Item =>
188	  policy.items.find((item) => item.type === damage.itemType)!;
189	
190	const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
191	  const desiredPayout = step.incident.damages.reduce(
192	    (total, damage) => total + payoutForDamage(damage, damagedItem(policy, damage)),
193	    0,
194	  );
195	  const payout = Math.min(desiredPayout, policy.remainingCap);
196	  policy.remainingCap -= payout;
197	  return { payout: Math.floor(payout), remainingCap: policy.remainingCap };
198	};
199	
200	const policyFor = (items: Item[]): Policy => ({
201	  items,
202	  remainingCap: insuranceSum(items) * CAP_MULTIPLIER,
203	});
204	
205	const countQuotesBefore = (steps: Step[], stepIndex: number): number =>
206	  steps.slice(0, stepIndex).filter((step) => step.op === "quote").length;
207	
208	export const runScenario = (scenario: Scenario): ScenarioOutput => {
209	  // A policy is registered under the index of the step that quoted it; that
210	  // step index is the id later claim steps refer to. Claims mutate their
211	  // policy's remainingCap, so the register carries state across steps.
212	  const policies = new Map<number, Policy>();
213	
214	  const results = scenario.steps.map((step, stepIndex): StepResult => {
215	    if (step.op === "claim") {
216	      return claim(step, policies.get(step.policy)!);
217	    }
218	    policies.set(stepIndex, policyFor(step.items));
219	    return quote(
220	      step,
221	      scenario.customer,
222	      countQuotesBefore(scenario.steps, stepIndex),
223	    );
224	  });
225	
226	  return { results };
227	};
